def _zeller_h(y, m, d):
    if m < 3:
        m += 12
        y -= 1
    K = y % 100
    J = y // 100
    return (d + (13 * (m + 1)) // 5 + K + K // 4 + J // 4 - 2 * J) % 7


def day_type(year, month, day):
    h = _zeller_h(year, month, day)
    return 'Weekend' if h in (0, 1) else 'Weekday'

def total_minutes_across_days(day_count, time_str):
    h, m = time_str.split(':')
    return day_count * 1440 + int(h) * 60 + int(m)
